def sync_products_to_odoo(
    odoo: OdooClient,
    limit: int = 0,
    brand_filter: str = "",
    dry_run: bool = False,
) -> Dict:
    """
    Sync products from embedded data to Odoo.

    Args:
        odoo: Connected OdooClient instance
        limit: Max products to sync (0 = all)
        brand_filter: Only sync products matching this brand/tenant
        dry_run: If True, just return what would be synced without creating

    Returns:
        Dict with results: created, skipped, errors, details
    """
    results = {
        "total": 0,
        "created": 0,
        "existing": 0,
        "errors": 0,
        "details": [],
    }

    products_to_sync = PRODUCTS
    if brand_filter:
        products_to_sync = [p for p in PRODUCTS if p["brand"].lower() == brand_filter.lower()]

    if limit > 0:
        products_to_sync = products_to_sync[:limit]

    results["total"] = len(products_to_sync)

    if dry_run:
        for p in products_to_sync:
            odoo_type = "product" if p["brand"] in STORABLE_BRANDS else "consu"
            results["details"].append({
                "sku": p["sku"],
                "name": p["name"],
                "brand": p["brand"],
                "odoo_type": odoo_type,
                "price": p["declared_value"],
                "weight": p["gross_weight"],
                "action": "would_create",
            })
        return results

    for p in products_to_sync:
        try:
            odoo_type = "product" if p["brand"] in STORABLE_BRANDS else "consu"

            # Search if product already exists
            existing = odoo._execute(
                "product.product", "search",
                [[["default_code", "=", p["sku"]]]],
            )

            if existing:
                results["existing"] += 1
                results["details"].append({
                    "sku": p["sku"],
                    "name": p["name"],
                    "brand": p["brand"],
                    "action": "exists",
                    "odoo_id": existing[0],
                })
                logger.info(f"Product already exists: {p['sku']} (ID={existing[0]})")
                continue

            # Build product values
            product_vals = {
                "name": p["name"],
                "default_code": p["sku"],
                "type": odoo_type,
                "sale_ok": True,
                "purchase_ok": True,
                "list_price": p["declared_value"],
                "standard_price": p["cost"],
                "weight": p["gross_weight"],
                "description_sale": p["description"],
            }

            # Try to set HS code
            if p["hs_code"]:
                try:
                    product_vals["x_hs_code"] = p["hs_code"]
                except Exception:
                    pass

            # Create product
            product_id = odoo._execute("product.product", "create", [product_vals])
            logger.info(f"Created product: {p['sku']} ({p['name']}) ID={product_id}")

            # Try to set brand field
            brand_set = False
            if p["brand"]:
                for field_name in ["x_studio_brand", "x_brand"]:
                    try:
                        odoo._execute(
                            "product.product", "write",
                            [[product_id], {field_name: p["brand"]}]
                        )
                        brand_set = True
                        logger.info(f"  Set {field_name}={p['brand']} on product {product_id}")
                        break
                    except Exception:
                        continue

            results["created"] += 1
            results["details"].append({
                "sku": p["sku"],
                "name": p["name"],
                "brand": p["brand"],
                "odoo_type": odoo_type,
                "action": "created",
                "odoo_id": product_id,
                "brand_set": brand_set,
            })

        except Exception as e:
            results["errors"] += 1
            results["details"].append({
                "sku": p["sku"],
                "name": p["name"],
                "brand": p["brand"],
                "action": "error",
                "error": str(e),
            })
            logger.error(f"Error creating product {p['sku']}: {e}")

    return results
